import{_ as e,c as l,b as p,a,d as r,w as t,r as i,o as c,e as o}from"./app-CXDlbpxe.js";const d={};function m(v,s){const n=i("RouteLink");return c(),l("div",null,[s[2]||(s[2]=p(`<h1 id="async-profiler-实战指南" tabindex="-1"><a class="header-anchor" href="#async-profiler-实战指南"><span>Async Profiler 实战指南</span></a></h1><h2 id="工具概述" tabindex="-1"><a class="header-anchor" href="#工具概述"><span>工具概述</span></a></h2><h3 id="什么是-async-profiler" tabindex="-1"><a class="header-anchor" href="#什么是-async-profiler"><span>什么是 Async Profiler</span></a></h3><p><strong>Async Profiler</strong> 是一款开源的高性能性能分析工具，由 OpenJDK 社区开发者创建和维护。与 JFR 相比，Async Profiler 提供了更丰富的分析维度和更灵活的采样配置，支持 CPU 采样、内存分配采样、锁分析、堆外内存追踪等多种分析模式。该工具基于 Linux perf 事件机制实现，能够在不修改目标 JVM 代码的情况下进行性能分析。</p><p>Async Profiler 的核心优势在于其<strong>低开销、高精度</strong>的特性。通过利用操作系统提供的性能监控接口，它能够在极低的性能开销下获取精确的性能数据。同时，Async Profiler 原生支持生成火焰图（Flame Graph），这种可视化方式能够直观地展示程序的调用栈和 CPU 时间分布，帮助开发者快速定位性能瓶颈。</p><h3 id="技术原理" tabindex="-1"><a class="header-anchor" href="#技术原理"><span>技术原理</span></a></h3><p>Async Profiler 的实现基于以下几个关键技术点：</p><p><strong>操作系统性能监控接口</strong>：在 Linux 系统上，Async Profiler 利用 <code>perf_event_open</code> 系统调用来收集性能数据。这个接口允许用户空间程序访问 CPU 的性能监控单元（PMU），获取诸如 CPU 周期、缓存命中率、指令执行等底层性能数据。通过这些数据，Async Profiler 能够精确地识别出程序的 CPU 热点。</p><p><strong>Java 虚拟机集成</strong>：Async Profiler 通过 JVM TI（Tool Interface）与 JVM 进行交互。JVM TI 是 JVM 提供的一套标准化接口，允许外部工具检查和控制 JVM 的运行状态。Async Profiler 利用 JVM TI 事件机制，在方法入口/出口、对象分配、锁操作等关键点插入性能监控代码。同时，它通过符号表解析来将 JVM 内部的地址信息转换为可读的方法名和类名。</p><p><strong>帧指针解析</strong>：要生成准确的调用栈信息，Async Profiler 需要解析程序的帧指针链。对于 Java 程序，这涉及到 JVM 内部栈帧结构的解析。Async Profiler 实现了对 HotSpot JVM 栈帧格式的深入理解，能够准确地还原出 Java 方法的调用链。</p><h3 id="与-jfr-的对比" tabindex="-1"><a class="header-anchor" href="#与-jfr-的对比"><span>与 JFR 的对比</span></a></h3><table><thead><tr><th>对比维度</th><th>Async Profiler</th><th>JFR</th></tr></thead><tbody><tr><td>开源协议</td><td>Apache 2.0</td><td>GPL v2 with Classpath Exception</td></tr><tr><td>采样开销</td><td>极低（基于 perf）</td><td>低（事件驱动）</td></tr><tr><td>分析维度</td><td>CPU、内存、锁、堆外内存</td><td>CPU、内存、GC、线程</td></tr><tr><td>火焰图</td><td>原生支持</td><td>需配合 JMC 或 jfr2 flames</td></tr><tr><td>生产环境适用性</td><td>⚠️ 需谨慎</td><td>✅ 推荐</td></tr><tr><td>配置灵活性</td><td>高</td><td>中</td></tr><tr><td>平台支持</td><td>Linux、macOS</td><td>全平台</td></tr></tbody></table><h2 id="安装与配置" tabindex="-1"><a class="header-anchor" href="#安装与配置"><span>安装与配置</span></a></h2><h3 id="环境要求" tabindex="-1"><a class="header-anchor" href="#环境要求"><span>环境要求</span></a></h3><p>Async Profiler 对运行环境有以下要求：</p><p><strong>操作系统支持</strong>：</p><ul><li>Linux：内核版本 2.6.32 及以上，推荐 4.4 以上以获得完整功能支持</li><li>macOS：10.13 (High Sierra) 及以上</li><li>Windows：有限支持，主要功能在 Linux/macOS 上可用</li></ul><p><strong>JVM 版本支持</strong>：</p><ul><li>OpenJDK 8 及以上</li><li>Oracle JDK 8 及以上</li><li>基于 HotSpot 的其他 JDK 发行版</li></ul><p><strong>硬件要求</strong>：</p><ul><li>支持 perf 事件 CPU（大多数现代 x86 和 ARM 处理器）</li><li>足够的权限访问 perf_event_open 接口</li></ul><h3 id="下载与安装" tabindex="-1"><a class="header-anchor" href="#下载与安装"><span>下载与安装</span></a></h3><p>从官方 GitHub 仓库下载预编译版本：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 下载最新版本</span></span>
<span class="line"><span class="token function">wget</span> https://github.com/async-profiler/async-profiler/releases/download/v2.9/async-profiler-2.9-linux-x64.tar.gz</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 解压</span></span>
<span class="line"><span class="token function">tar</span> <span class="token parameter variable">-xzf</span> async-profiler-2.9-linux-x64.tar.gz</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 进入目录</span></span>
<span class="line"><span class="token builtin class-name">cd</span> async-profiler-2.9-linux-x64</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对于 macOS 系统：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 下载 macOS 版本</span></span>
<span class="line"><span class="token function">wget</span> https://github.com/async-profiler/async-profiler/releases/download/v2.9/async-profiler-2.9-macos-x64.tar.gz</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 解压</span></span>
<span class="line"><span class="token function">tar</span> <span class="token parameter variable">-xzf</span> async-profiler-2.9-macos-x64.tar.gz</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 进入目录</span></span>
<span class="line"><span class="token builtin class-name">cd</span> async-profiler-2.9-macos-x64</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="权限配置" tabindex="-1"><a class="header-anchor" href="#权限配置"><span>权限配置</span></a></h3><p>在 Linux 系统上，使用 Async Profiler 需要适当的权限。常见的权限问题解决方案：</p><p><strong>方案一：调整 procfs 权限</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 临时调整（需要 root 权限）</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token parameter variable">-1</span> <span class="token operator">|</span> <span class="token function">sudo</span> <span class="token function">tee</span> /proc/sys/kernel/perf_event_paranoid</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>方案二：永久调整（需要修改 sysctl 配置）</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 在 /etc/sysctl.conf 中添加</span></span>
<span class="line">kernel.perf_event_paranoid <span class="token operator">=</span> <span class="token parameter variable">-1</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 应用配置</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token function">sysctl</span> <span class="token parameter variable">-p</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>方案三：使用 perf 事件组</strong></p><p>如果无法调整系统权限，可以让进程通过 perf 事件组获取权限：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 创建 perf 用户组</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token function">groupadd</span> perf</span>
<span class="line"><span class="token function">sudo</span> <span class="token function">usermod</span> <span class="token parameter variable">-a</span> <span class="token parameter variable">-G</span> perf <span class="token environment constant">$USER</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 设置 perf 事件权限</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token function">chgrp</span> perf /sys/kernel/debug/tracing/trace_marker</span>
<span class="line"><span class="token function">sudo</span> <span class="token function">chmod</span> g+w /sys/kernel/debug/tracing/trace_marker</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="验证安装" tabindex="-1"><a class="header-anchor" href="#验证安装"><span>验证安装</span></a></h3><p>运行内置的健康检查脚本验证安装：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 检查系统环境</span></span>
<span class="line">jps <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&quot;Application|$&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 运行测试脚本</span></span>
<span class="line">./profiler.sh <span class="token builtin class-name">test</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或者使用 Java 测试类</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-jar</span> profiler.jar <span class="token builtin class-name">test</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="核心功能详解" tabindex="-1"><a class="header-anchor" href="#核心功能详解"><span>核心功能详解</span></a></h2><h3 id="cpu-热点分析" tabindex="-1"><a class="header-anchor" href="#cpu-热点分析"><span>CPU 热点分析</span></a></h3><p>CPU 热点分析是 Async Profiler 最常用的功能，它通过定时采样来识别消耗 CPU 时间最多的代码路径。分析结果通常以火焰图或调用树的形式展示，帮助开发者快速找到性能优化的切入点。</p><p><strong>采样原理</strong>：Async Profiler 使用硬件性能监控单元（PMU）来采样 CPU 周期或指令。每隔固定的时间间隔（默认 1ms）， profiler 会中断目标进程，读取当前 CPU 寄存器的返回地址（RIP/EIP），并将其记录为一次采样。通过大量的采样统计，可以推断出各个代码路径被 CPU 执行的频率。</p><p><strong>启动 CPU 采样</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 基本用法 - 采样 60 秒</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/cpu-profile.html <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 指定采样间隔（单位：纳秒）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-i</span> <span class="token number">1000000</span> <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/cpu-profile.html <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 CPU 周期作为采样事件（需要硬件支持）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-e</span> cycles <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/cpu-profile.html <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用指令作为采样事件（更精确的 CPU 指令执行分析）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-e</span> instructions <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/cpu-profile.html <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>采样事件对比</strong>：</p><table><thead><tr><th>采样事件</th><th>适用场景</th><th>特点</th></tr></thead><tbody><tr><td>cpu</td><td>通用 CPU 分析</td><td>默认选项，适合大多数场景</td></tr><tr><td>cycles</td><td>CPU 密集型分析</td><td>反映真实 CPU 执行时间</td></tr><tr><td>instructions</td><td>微架构分析</td><td>忽略缓存影响，关注指令数</td></tr><tr><td>cache-misses</td><td>缓存优化</td><td>识别缓存不友好的代码</td></tr><tr><td>branch-misses</td><td>分支预测优化</td><td>识别预测错误的分支</td></tr></tbody></table><p><strong>结果分析</strong>：CPU 采样结果以火焰图形式展示，横条宽度代表该方法消耗的 CPU 时间比例。火焰图的阅读方法是从下到上看，底部的框表示程序的入口方法（如 main），顶部的框表示 CPU 当前正在执行的方法。宽度越宽的方法，表示被采样的次数越多，也就是 CPU 时间消耗越多。</p><h3 id="内存分配分析" tabindex="-1"><a class="header-anchor" href="#内存分配分析"><span>内存分配分析</span></a></h3><p>内存分配分析用于识别程序中的内存分配热点，帮助开发者发现过度分配或不当分配的问题。这对于优化 GC 压力、减少内存占用非常重要。</p><p><strong>分析原理</strong>：Async Profiler 通过 Hook JVM 的对象分配函数（如 <code>unsafe_alloc</code>、<code>object_alloc</code> 等）来拦截内存分配事件。每次分配发生时，profiler 记录分配的大小、对象类型和调用栈信息。通过统计分析，可以识别出分配最频繁的对象类型和分配路径。</p><p><strong>启动内存分配分析</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 基础内存分配分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/memory-profile.html <span class="token parameter variable">-e</span> alloc <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 设置分配采样率（每 N 字节采样一次）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/memory-profile.html <span class="token parameter variable">-e</span> alloc <span class="token parameter variable">--alloc</span><span class="token operator">=</span><span class="token operator">&lt;</span>bytes<span class="token operator">&gt;</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 对象分配分析（按对象类型聚合）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/object-profile.html <span class="token parameter variable">-e</span> object-alloc <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 小对象分配分析（优化堆空间利用）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/small-alloc.html <span class="token parameter variable">-e</span> small-alloc <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>内存分配参数说明</strong>：</p><table><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>-e alloc</td><td>捕获所有对象分配</td><td>默认采样所有分配</td></tr><tr><td>--alloc=512k</td><td>设置采样阈值</td><td>只记录大于 512KB 的分配</td></tr><tr><td>-e object-alloc</td><td>按对象类型统计分配</td><td>关注分配的对象类型</td></tr><tr><td>-e small-alloc</td><td>小对象分配分析</td><td>优化内存碎片化</td></tr></tbody></table><p><strong>分析结果解读</strong>：内存分配火焰图与 CPU 火焰图类似，但横条宽度代表分配的内存总量。通过分析分配火焰图，可以识别出：</p><ul><li>分配量最大的对象类型（可能是优化目标）</li><li>分配最频繁的方法（热点分配路径）</li><li>分配与实际使用的差异（可能存在内存泄漏）</li></ul><h3 id="锁分析" tabindex="-1"><a class="header-anchor" href="#锁分析"><span>锁分析</span></a></h3><p>锁分析用于识别线程同步中的竞争问题，帮助开发者发现死锁、锁竞争激烈等问题。</p><p><strong>分析原理</strong>：Async Profiler 通过监控 Java 对象监视器的获取和释放事件，记录锁的等待时间和竞争情况。当线程尝试获取一个被其他线程持有的锁时，profiler 会记录这次等待事件，包括等待的线程、持有锁的线程和等待时长。</p><p><strong>启动锁分析</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 基础锁分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/lock-profile.html <span class="token parameter variable">-e</span> lock <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 细粒度锁分析（记录锁地址）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/detailed-lock.html <span class="token parameter variable">-e</span> lock <span class="token parameter variable">-o</span> collapsed <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 等待时间分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/wait-time.html <span class="token parameter variable">-e</span> lock_wait <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>锁分析指标</strong>：</p><table><thead><tr><th>指标</th><th>说明</th><th>优化建议</th></tr></thead><tbody><tr><td>锁竞争次数</td><td>线程尝试获取锁的次数</td><td>减少锁粒度或使用并发数据结构</td></tr><tr><td>平均等待时间</td><td>线程获取锁的平均等待时长</td><td>缩短临界区代码</td></tr><tr><td>最大等待时间</td><td>单次最长等待时间</td><td>识别热点锁</td></tr><tr><td>死锁</td><td>检测到的死锁情况</td><td>重构锁使用方式</td></tr></tbody></table><h3 id="堆外内存分析" tabindex="-1"><a class="header-anchor" href="#堆外内存分析"><span>堆外内存分析</span></a></h3><p>堆外内存分析用于追踪 JVM 堆之外的内存分配，这对于使用 NIO DirectBuffer、Native 代码（JNI）等场景特别重要。</p><p><strong>分析原理</strong>：Async Profiler 通过跟踪 <code>malloc</code>、<code>mmap</code>、<code>mprotect</code> 等系统调用来监控堆外内存分配。对于 Java 程序，这主要用于分析 DirectByteBuffer、内存映射文件和 JNI 代码的内存使用。</p><p><strong>启动堆外内存分析</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 堆外内存分配分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/native-memory.html <span class="token parameter variable">-e</span> native <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 内存映射分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/mmap-profile.html <span class="token parameter variable">-e</span> mmap <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 完整的内存分析（包含堆内和堆外）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/full-memory.html <span class="token parameter variable">-e</span> memory <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="wall-clock-分析" tabindex="-1"><a class="header-anchor" href="#wall-clock-分析"><span>Wall Clock 分析</span></a></h3><p>Wall Clock 分析用于了解程序的实际执行时间分布，特别适用于分析 I/O 等待、线程休眠等不消耗 CPU 的时间。</p><p><strong>分析原理</strong>：与 CPU 采样不同，Wall Clock 采样不依赖于 CPU 周期，而是按实际时间间隔采样。这使得它能够捕获到所有执行状态，包括睡眠、等待 I/O 等状态。</p><p><strong>启动 Wall Clock 分析</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># Wall Clock 时间分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/wall-clock.html <span class="token parameter variable">-e</span> wall <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 带有线程状态的 Wall Clock 分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/wall-thread.html <span class="token parameter variable">-e</span> wall <span class="token parameter variable">-t</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="输出格式详解" tabindex="-1"><a class="header-anchor" href="#输出格式详解"><span>输出格式详解</span></a></h2><h3 id="flame-graph-格式" tabindex="-1"><a class="header-anchor" href="#flame-graph-格式"><span>Flame Graph 格式</span></a></h3><p>火焰图是 Async Profiler 最常用的输出格式，由 Brendan Gregg 创建。这种可视化方式能够直观地展示程序的调用栈结构和性能分布。</p><p><strong>SVG 格式（推荐）</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 生成 SVG 火焰图（可交互）</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成带颜色编码的 SVG</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile-color.svg <span class="token parameter variable">-p</span> red <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>交互式 SVG 功能</strong>：</p><ul><li>点击任意方块会高亮显示该方法的所有调用路径</li><li>搜索框可以快速定位特定方法</li><li>鼠标悬停显示方法名和采样比例</li><li>双击可放大特定区域</li></ul><p><strong>HTML 格式（带搜索）</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 生成自包含的 HTML 报告</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.html <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成带 JavaScript 交互的 HTML</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile-full.html <span class="token parameter variable">-o</span> <span class="token assign-left variable">html</span><span class="token operator">=</span>js <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="collapsed-stack-格式" tabindex="-1"><a class="header-anchor" href="#collapsed-stack-格式"><span>Collapsed Stack 格式</span></a></h3><p>Collapsed Stack 格式是一种纯文本格式，每行记录一次完整的调用栈，适合用于生成其他工具的分析结果或进行自定义处理。</p><p><strong>生成 Collapsed Stack</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 生成 collapsed 格式</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.col <span class="token parameter variable">-o</span> collapsed <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 示例输出格式：</span></span>
<span class="line"><span class="token comment"># java/lang/Thread.run:java/lang/Thread.exit:java/lang/Thread.exit:java/util/concurrent/ThreadPoolExecutor$Worker.run:java/util/concurrent/ThreadPoolExecutor.runWorker:java/util/concurrent/ThreadPoolExecutor.postSubmit:java/util/concurrent/ExecutorService.submit 1234</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>使用 FlameGraph 工具渲染</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 下载 FlameGraph 工具</span></span>
<span class="line"><span class="token function">git</span> clone https://github.com/brendangregg/FlameGraph.git</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成 SVG</span></span>
<span class="line">./FlameGraph/flamegraph.pl /tmp/profile.col <span class="token operator">&gt;</span> /tmp/flamegraph.svg</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成反向火焰图（从叶节点看调用者）</span></span>
<span class="line">./FlameGraph/flamegraph.pl <span class="token parameter variable">--reverse</span> /tmp/profile.col <span class="token operator">&gt;</span> /tmp/reverse-flamegraph.svg</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="call-tree-格式" tabindex="-1"><a class="header-anchor" href="#call-tree-格式"><span>Call Tree 格式</span></a></h3><p>Call Tree 格式以树形结构展示调用关系，适合理解程序的结构和调用依赖。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 生成 call tree 格式</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.ct <span class="token parameter variable">-o</span> calltree <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 示例输出：</span></span>
<span class="line"><span class="token comment"># - 100% java.lang.Thread.run</span></span>
<span class="line"><span class="token comment">#   - 80% java.util.concurrent.ThreadPoolExecutor.runWorker</span></span>
<span class="line"><span class="token comment">#     - 60% com.example.Service.process</span></span>
<span class="line"><span class="token comment">#       - 40% com.example.Service.queryDatabase</span></span>
<span class="line"><span class="token comment">#       - 20% com.example.Service.transform</span></span>
<span class="line"><span class="token comment">#   - 20% java.util.concurrent.FutureTask.run</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="jfr-格式转换" tabindex="-1"><a class="header-anchor" href="#jfr-格式转换"><span>JFR 格式转换</span></a></h3><p>Async Profiler 支持导出为 JFR 格式，便于使用 JMC 进行分析：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 转换为 JFR 格式</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.jfr <span class="token parameter variable">-o</span> jfr <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 jcmd 转换为 JFR</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>pid<span class="token operator">&gt;</span> JFR.start</span>
<span class="line"><span class="token function">sleep</span> <span class="token number">60</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>pid<span class="token operator">&gt;</span> JFR.dump <span class="token assign-left variable">name</span><span class="token operator">=</span>recording1 <span class="token assign-left variable">filename</span><span class="token operator">=</span>/tmp/profile.jfr</span>
<span class="line">jcmd <span class="token operator">&lt;</span>pid<span class="token operator">&gt;</span> JFR.stop</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="实战案例" tabindex="-1"><a class="header-anchor" href="#实战案例"><span>实战案例</span></a></h2><h3 id="案例一-web-服务-cpu-优化" tabindex="-1"><a class="header-anchor" href="#案例一-web-服务-cpu-优化"><span>案例一：Web 服务 CPU 优化</span></a></h3><p><strong>背景</strong>：一个 REST API 服务响应时间不稳定，CPU 使用率偏高。</p><p><strong>诊断步骤</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 1. 获取服务进程 ID</span></span>
<span class="line">jps <span class="token operator">|</span> <span class="token function">grep</span> Application</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. CPU 采样分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> cycles <span class="token parameter variable">-f</span> /tmp/cpu.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. 分析发现 JSON 序列化是热点</span></span>
<span class="line"><span class="token comment"># 火焰图显示 org.springframework.jackson 消耗大量 CPU</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优化措施</strong>：</p><ul><li>替换 JSON 库为高性能实现</li><li>启用 JSON 序列化缓存</li><li>使用二进制协议（如 Protocol Buffers）</li></ul><p><strong>效果验证</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 优化后重新采样对比</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> cycles <span class="token parameter variable">-f</span> /tmp/cpu-after.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># CPU 使用率从 75% 降至 45%，响应时间 P99 从 200ms 降至 80ms</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="案例二-内存分配优化" tabindex="-1"><a class="header-anchor" href="#案例二-内存分配优化"><span>案例二：内存分配优化</span></a></h3><p><strong>背景</strong>：批处理作业频繁触发 Full GC，导致处理速度下降。</p><p><strong>诊断步骤</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 1. 内存分配分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> alloc <span class="token parameter variable">-f</span> /tmp/alloc.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 发现 String 操作产生大量临时对象</span></span>
<span class="line"><span class="token comment"># 3. 进一步分析 StringBuilder 分配</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> alloc <span class="token parameter variable">-f</span> /tmp/string-alloc.svg <span class="token parameter variable">--alloc</span><span class="token operator">=</span>100b <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优化措施</strong>：</p><ul><li>避免在循环中创建 String 对象</li><li>使用 StringBuilder 复用池</li><li>优化日志框架的格式化方式</li></ul><h3 id="案例三-锁竞争排查" tabindex="-1"><a class="header-anchor" href="#案例三-锁竞争排查"><span>案例三：锁竞争排查</span></a></h3><p><strong>背景</strong>：高并发场景下线程阻塞严重，TPS 无法提升。</p><p><strong>诊断步骤</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 1. 锁竞争分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> lock <span class="token parameter variable">-f</span> /tmp/lock.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 发现某个 ConcurrentHashMap 竞争激烈</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> lock_wait <span class="token parameter variable">-f</span> /tmp/lock-wait.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 3. 分析锁持有者的执行情况</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/holder.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优化措施</strong>：</p><ul><li>分析发现是热点数据项的锁竞争</li><li>调整数据结构设计，避免热点数据</li><li>使用细粒度锁或无锁数据结构</li></ul><h3 id="案例四-异步-i-o-优化" tabindex="-1"><a class="header-anchor" href="#案例四-异步-i-o-优化"><span>案例四：异步 I/O 优化</span></a></h3><p><strong>背景</strong>：异步 I/O 应用程序响应慢，但 CPU 使用率不高。</p><p><strong>诊断步骤</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># Wall Clock 分析</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> wall <span class="token parameter variable">-f</span> /tmp/wall.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 发现大量时间花费在 I/O 等待上</span></span>
<span class="line"><span class="token comment"># 进一步分析网络 I/O</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> network <span class="token parameter variable">-f</span> /tmp/network.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优化措施</strong>：</p><ul><li>增加连接池大小</li><li>调整缓冲区配置</li><li>优化超时策略</li></ul><h2 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践"><span>最佳实践</span></a></h2><h3 id="生产环境使用建议" tabindex="-1"><a class="header-anchor" href="#生产环境使用建议"><span>生产环境使用建议</span></a></h3><p><strong>安全使用原则</strong>：</p><ul><li>生产环境优先使用 JFR 进行基础监控</li><li>Async Profiler 仅在性能问题排查时临时启用</li><li>设置合理的采样时间（通常 30 秒到 5 分钟）</li><li>在低峰期进行分析，避免影响业务</li></ul><p><strong>采样参数选择</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 生产问题排查 - 较短时间，高采样率</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">30</span> <span class="token parameter variable">-i</span> <span class="token number">500000</span> <span class="token parameter variable">-f</span> /tmp/profile.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 开发环境分析 - 较长时间，正常采样率</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">120</span> <span class="token parameter variable">-f</span> /tmp/profile-dev.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 内存分析 - 使用更精细的采样</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-e</span> alloc <span class="token parameter variable">--alloc</span><span class="token operator">=</span>10k <span class="token parameter variable">-f</span> /tmp/alloc.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="性能影响评估" tabindex="-1"><a class="header-anchor" href="#性能影响评估"><span>性能影响评估</span></a></h3><p>Async Profiler 的性能开销取决于多个因素：</p><table><thead><tr><th>分析类型</th><th>典型开销</th><th>说明</th></tr></thead><tbody><tr><td>CPU 分析</td><td>1-5%</td><td>采样间隔越短，开销越大</td></tr><tr><td>内存分配分析</td><td>5-15%</td><td>取决于分配频率</td></tr><tr><td>锁分析</td><td>1-3%</td><td>开销较小</td></tr><tr><td>Wall Clock</td><td>1-2%</td><td>开销最小</td></tr></tbody></table><h3 id="与-ci-cd-集成" tabindex="-1"><a class="header-anchor" href="#与-ci-cd-集成"><span>与 CI/CD 集成</span></a></h3><p>将性能分析集成到持续集成流程中：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># performance-check.sh</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jps <span class="token operator">|</span> <span class="token function">grep</span> Application <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-n</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;Running performance analysis...&quot;</span></span>
<span class="line">    ./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/ci-profile.svg <span class="token variable">$PID</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># 检查是否存在异常热点</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token function">grep</span> <span class="token parameter variable">-q</span> <span class="token string">&quot;expensive_operation&quot;</span> /tmp/ci-profile.svg<span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">        <span class="token builtin class-name">echo</span> <span class="token string">&quot;WARNING: Potential performance issue detected&quot;</span></span>
<span class="line">        <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line">    <span class="token keyword">fi</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;Performance check passed&quot;</span></span>
<span class="line"><span class="token keyword">else</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;No application found, skipping performance check&quot;</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="常见问题与解决方案" tabindex="-1"><a class="header-anchor" href="#常见问题与解决方案"><span>常见问题与解决方案</span></a></h2><h3 id="权限问题" tabindex="-1"><a class="header-anchor" href="#权限问题"><span>权限问题</span></a></h3><p><strong>问题</strong>：启动 profiler 时报错 &quot;Permission denied&quot;</p><p><strong>解决方案</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 检查 perf_event_paranoid 值</span></span>
<span class="line"><span class="token function">cat</span> /proc/sys/kernel/perf_event_paranoid</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 临时禁用</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token parameter variable">-1</span> <span class="token operator">|</span> <span class="token function">sudo</span> <span class="token function">tee</span> /proc/sys/kernel/perf_event_paranoid</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 永久修改</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;kernel.perf_event_paranoid = -1&quot;</span> <span class="token operator">|</span> <span class="token function">sudo</span> <span class="token function">tee</span> <span class="token parameter variable">-a</span> /etc/sysctl.conf</span>
<span class="line"><span class="token function">sudo</span> <span class="token function">sysctl</span> <span class="token parameter variable">-p</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="符号解析问题" tabindex="-1"><a class="header-anchor" href="#符号解析问题"><span>符号解析问题</span></a></h3><p><strong>问题</strong>：火焰图中只显示地址，不显示方法名</p><p><strong>解决方案</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 确保 JDK 的符号表可用</span></span>
<span class="line"><span class="token comment"># 使用 debug 版本的 JVM</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-XshowSettings:vm</span> <span class="token parameter variable">-version</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 如果使用容器，需要挂载 /usr/lib/jvm</span></span>
<span class="line"><span class="token function">docker</span> run <span class="token parameter variable">-v</span> /usr/lib/jvm:/usr/lib/jvm <span class="token punctuation">..</span>.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="采样不准确" tabindex="-1"><a class="header-anchor" href="#采样不准确"><span>采样不准确</span></a></h3><p><strong>问题</strong>：采样结果与预期不符，某些方法未被采样</p><p><strong>解决方案</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 尝试不同的采样事件</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-e</span> cycles <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-e</span> instructions <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 增加采样时间</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">180</span> <span class="token parameter variable">-f</span> /tmp/profile.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 调整采样间隔</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-i</span> <span class="token number">100000</span> <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile.svg <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="容器环境问题" tabindex="-1"><a class="header-anchor" href="#容器环境问题"><span>容器环境问题</span></a></h3><p><strong>问题</strong>：在 Docker/Kubernetes 环境中无法使用</p><p><strong>解决方案</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># Docker 运行时配置</span></span>
<span class="line"><span class="token function">docker</span> run --cap-add<span class="token operator">=</span>SYS_PTRACE --security-opt <span class="token assign-left variable">seccomp</span><span class="token operator">=</span>unconfined <span class="token punctuation">..</span>.</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Kubernetes Pod 配置</span></span>
<span class="line">securityContext:</span>
<span class="line">  capabilities:</span>
<span class="line">    add:</span>
<span class="line">      - SYS_PTRACE</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 挂载必要的目录</span></span>
<span class="line"><span class="token parameter variable">-v</span> /usr/lib/jvm:/usr/lib/jvm</span>
<span class="line"><span class="token parameter variable">-v</span> /sys/kernel/debug:/sys/kernel/debug</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="进阶技巧" tabindex="-1"><a class="header-anchor" href="#进阶技巧"><span>进阶技巧</span></a></h2><h3 id="自定义事件分析" tabindex="-1"><a class="header-anchor" href="#自定义事件分析"><span>自定义事件分析</span></a></h3><p>Async Profiler 支持通过 Java Agent 注入自定义事件：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 自定义采样点</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">CustomSampler</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">sample</span><span class="token punctuation">(</span><span class="token class-name">String</span> context<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">StackTraceElement</span><span class="token punctuation">[</span><span class="token punctuation">]</span> stack <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Throwable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getStackTrace</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">// 将采样数据写入 profiler</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="多进程分析" tabindex="-1"><a class="header-anchor" href="#多进程分析"><span>多进程分析</span></a></h3><p>分析包含多个进程的应用系统：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 采集所有相关进程</span></span>
<span class="line"><span class="token assign-left variable">PIDS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>pgrep <span class="token parameter variable">-f</span> <span class="token string">&quot;com.example&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token keyword">for</span> <span class="token for-or-select variable">PID</span> <span class="token keyword">in</span> <span class="token variable">$PIDS</span><span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">    ./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/profile-<span class="token variable">$PID</span>.svg <span class="token variable">$PID</span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 合并结果</span></span>
<span class="line"><span class="token function">cat</span> /tmp/profile-*.col <span class="token operator">&gt;</span> /tmp/merged.col</span>
<span class="line">./FlameGraph/flamegraph.pl /tmp/merged.col <span class="token operator">&gt;</span> /tmp/merged.svg</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="增量分析" tabindex="-1"><a class="header-anchor" href="#增量分析"><span>增量分析</span></a></h3><p>对比不同时间段的性能数据：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 基准测试</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/baseline.col <span class="token parameter variable">-o</span> collapsed <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 优化后测试</span></span>
<span class="line">./profiler.sh <span class="token parameter variable">-d</span> <span class="token number">60</span> <span class="token parameter variable">-f</span> /tmp/after.col <span class="token parameter variable">-o</span> collapsed <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 flamegraph-diff.pl 对比</span></span>
<span class="line">./FlameGraph/flamegraph-diff.pl /tmp/baseline.col /tmp/after.col <span class="token operator">&gt;</span> /tmp/diff.svg</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="相关资源" tabindex="-1"><a class="header-anchor" href="#相关资源"><span>相关资源</span></a></h2><p><strong>官方资源</strong>：</p><ul><li><a href="https://github.com/async-profiler/async-profiler" target="_blank" rel="noopener noreferrer">Async Profiler GitHub</a></li><li><a href="https://github.com/brendangregg/FlameGraph" target="_blank" rel="noopener noreferrer">FlameGraph 工具集</a></li><li><a href="https://github.com/async-profiler/async-profiler/wiki" target="_blank" rel="noopener noreferrer">Async Profiler Wiki</a></li></ul><p><strong>学习资源</strong>：</p><ul><li><a href="http://www.brendangregg.com/" target="_blank" rel="noopener noreferrer">Brendan Gregg 的性能分析博客</a></li><li><a href="https://netflixtechblog.com/" target="_blank" rel="noopener noreferrer">Netflix 技术博客 - 性能分析实践</a></li><li><a href="https://code.facebook.com/posts/971137969217467/" target="_blank" rel="noopener noreferrer">Facebook 的性能分析实践</a></li></ul><p><strong>相关工具对比</strong>：</p>`,166)),a("ul",null,[a("li",null,[r(n,{to:"/java/advanced/diagnostic-tools/jfr-enhancements.html"},{default:t(()=>s[0]||(s[0]=[o("JFR 性能监控增强详解")])),_:1,__:[0]})]),s[1]||(s[1]=a("li",null,[a("a",{href:"https://docs.oracle.com/en/java/java-components/jdk-mission-control/",target:"_blank",rel:"noopener noreferrer"},"Java Mission Control 官方文档")],-1))])])}const b=e(d,[["render",m]]),k=JSON.parse('{"path":"/java/advanced/diagnostic-tools/profiling-async-profiler.html","title":"Async Profiler 实战指南","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1767688846000,"contributors":[{"name":"zhaomy","username":"zhaomy","email":"3036190149@qq.com","commits":1,"url":"https://github.com/zhaomy"}],"changelog":[{"hash":"002042d6ccab469ab518aca6e5eb5ee2c566721e","time":1767688846000,"email":"3036190149@qq.com","author":"zhaomy","message":"docs: 新增Java诊断与监控工具相关文档"}]},"filePathRelative":"java/advanced/diagnostic-tools/profiling-async-profiler.md","excerpt":"\\n<h2>工具概述</h2>\\n<h3>什么是 Async Profiler</h3>\\n<p><strong>Async Profiler</strong> 是一款开源的高性能性能分析工具，由 OpenJDK 社区开发者创建和维护。与 JFR 相比，Async Profiler 提供了更丰富的分析维度和更灵活的采样配置，支持 CPU 采样、内存分配采样、锁分析、堆外内存追踪等多种分析模式。该工具基于 Linux perf 事件机制实现，能够在不修改目标 JVM 代码的情况下进行性能分析。</p>\\n<p>Async Profiler 的核心优势在于其<strong>低开销、高精度</strong>的特性。通过利用操作系统提供的性能监控接口，它能够在极低的性能开销下获取精确的性能数据。同时，Async Profiler 原生支持生成火焰图（Flame Graph），这种可视化方式能够直观地展示程序的调用栈和 CPU 时间分布，帮助开发者快速定位性能瓶颈。</p>"}');export{b as comp,k as data};
